import{_ as a,o as t,c as o,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const m=JSON.parse('{"title":"Prerequisites","description":"","frontmatter":{},"headers":[],"relativePath":"guide/prerequisites.md","filePath":"guide/prerequisites.md"}'),i={name:"guide/prerequisites.md"};function l(n,e,s,u,d,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h1><p>Before deploying Cloud Mail, make sure you have the following ready.</p><h2 id="_1-cloudflare-account" tabindex="-1">1. Cloudflare Account <a class="header-anchor" href="#_1-cloudflare-account" aria-label="Permalink to &quot;1. Cloudflare Account&quot;">​</a></h2><p>Register (or log in) at <a href="https://dash.cloudflare.com/" target="_blank" rel="noreferrer">dash.cloudflare.com</a>.</p><p>You&#39;ll need access to:</p><ul><li><strong>Workers &amp; Pages</strong> — to run the application</li><li><strong>D1</strong> — SQLite database</li><li><strong>KV</strong> — key-value cache</li><li><strong>R2</strong> — file/attachment storage</li><li><strong>Email Routing</strong> — to receive emails</li></ul><h2 id="_2-domain-name" tabindex="-1">2. Domain Name <a class="header-anchor" href="#_2-domain-name" aria-label="Permalink to &quot;2. Domain Name&quot;">​</a></h2><p>You need a domain name added to Cloudflare (with nameservers pointing to Cloudflare). This is required for:</p><ul><li><strong>Custom Worker Domain</strong> — so users can access the dashboard</li><li><strong>Email Routing</strong> — to receive emails at your custom domain</li></ul><h2 id="_3-resend-account" tabindex="-1">3. Resend Account <a class="header-anchor" href="#_3-resend-account" aria-label="Permalink to &quot;3. Resend Account&quot;">​</a></h2><p>Cloud Mail uses <a href="https://resend.com" target="_blank" rel="noreferrer">Resend</a> to send outgoing emails.</p><ul><li>Sign up for a free Resend account</li><li>Verify your domain in Resend</li><li>Get your API key</li></ul><p><strong>Free tier</strong> allows 100 emails/day — enough for testing and light use.</p><h2 id="_4-github-account" tabindex="-1">4. GitHub Account <a class="header-anchor" href="#_4-github-account" aria-label="Permalink to &quot;4. GitHub Account&quot;">​</a></h2><p>You need a GitHub account to fork the repository.</p><p><a href="https://github.com/maillab/cloud-mail" target="_blank" rel="noreferrer">https://github.com/maillab/cloud-mail</a></p><hr><p>Once you have all of the above, proceed to:</p><ul><li><a href="/guide/dashboard.html">Dashboard Deployment</a> — for manual setup</li><li><a href="/guide/action.html">GitHub Actions Deployment</a> — for automated deployment</li></ul>',19)])])}const p=a(i,[["render",l]]);export{m as __pageData,p as default};
